package io.github.diodeme.ji.extension;

import io.github.diodeme.ji.ai.CancellationToken;
import java.nio.charset.Charset;
import java.nio.charset.StandardCharsets;
import java.time.Duration;
import java.util.List;
import java.util.Map;
import java.util.OptionalLong;

/** Workspace-scoped file and process capability; callers never authorize raw host paths. */
public interface WorkspaceProvider extends AutoCloseable {
    WorkspaceIdentity identity();

    WorkspacePath resolve(String path, Access access);

    FileContent read(WorkspacePath path, ReadOptions options, CancellationToken cancellation);

    MutationResult write(WorkspacePath path, byte[] content, OptionalLong expectedRevision,
                         CancellationToken cancellation);

    MutationResult edit(WorkspacePath path, List<Replacement> replacements, long expectedRevision,
                        CancellationToken cancellation);

    ProcessResult execute(ProcessRequest request, CancellationToken cancellation);

    @Override
    default void close() {}

    enum Access { READ, WRITE, EXECUTE }

    record WorkspaceIdentity(String workspaceId, long generation) {
        public WorkspaceIdentity {
            requireText(workspaceId, "workspaceId");
            if (generation < 0) throw new IllegalArgumentException("generation must be non-negative");
        }
    }

    record WorkspacePath(WorkspaceIdentity workspace, String canonicalPath, String relativePath,
                         Access access, long capabilityRevision) {
        public WorkspacePath {
            if (workspace == null || access == null) throw new IllegalArgumentException("workspace path fields must not be null");
            requireText(canonicalPath, "canonicalPath");
            requireText(relativePath, "relativePath");
            if (capabilityRevision < 0) throw new IllegalArgumentException("capabilityRevision must be non-negative");
        }
    }

    record ReadOptions(long offset, long limit, int maxLines, int maxBytes, Charset charset) {
        public static final int PI_MAX_LINES = 2_000;
        public static final int PI_MAX_BYTES = 50 * 1_024;

        public ReadOptions {
            if (offset < 1 || limit < 1 || maxLines < 1 || maxBytes < 1) {
                throw new IllegalArgumentException("read bounds must be positive");
            }
            if (charset == null) throw new IllegalArgumentException("charset must not be null");
        }

        public static ReadOptions text(long offset, long limit) {
            return new ReadOptions(offset, limit, PI_MAX_LINES, PI_MAX_BYTES, StandardCharsets.UTF_8);
        }
    }

    record FileContent(byte[] bytes, long revision, long totalLines, boolean truncated,
                       String truncatedBy, long nextOffset) {
        public FileContent {
            bytes = bytes.clone();
            if (revision < 0 || totalLines < 0 || nextOffset < 0) {
                throw new IllegalArgumentException("file metadata must be non-negative");
            }
            truncatedBy = truncatedBy == null ? "" : truncatedBy;
        }

        @Override
        public byte[] bytes() {
            return bytes.clone();
        }

        public String text(Charset charset) {
            return new String(bytes, charset);
        }
    }

    record MutationResult(long revision, long bytesWritten) {
        public MutationResult {
            if (revision < 1 || bytesWritten < 0) throw new IllegalArgumentException("invalid mutation result");
        }
    }

    record Replacement(String oldText, String newText) {
        public Replacement {
            if (oldText == null || oldText.isEmpty()) throw new IllegalArgumentException("oldText must not be empty");
            if (newText == null) throw new IllegalArgumentException("newText must not be null");
        }
    }

    sealed interface Command permits Command.Argv, Command.Shell {
        record Argv(List<String> arguments) implements Command {
            public Argv {
                arguments = List.copyOf(arguments);
                if (arguments.isEmpty() || arguments.stream().anyMatch(value -> value == null || value.isEmpty())) {
                    throw new IllegalArgumentException("argv must contain non-empty arguments");
                }
            }
        }

        record Shell(String command) implements Command {
            public Shell {
                requireText(command, "command");
            }
        }
    }

    record ProcessRequest(WorkspaceIdentity workspace, Command command, WorkspacePath cwd,
                          Map<String, String> environment, Duration timeout) {
        public ProcessRequest {
            if (workspace == null || command == null || cwd == null || timeout == null) {
                throw new IllegalArgumentException("process request fields must not be null");
            }
            environment = Map.copyOf(environment);
            if (timeout.isZero() || timeout.isNegative()) throw new IllegalArgumentException("timeout must be positive");
        }
    }

    record ProcessResult(int exitCode, byte[] stdout, byte[] stderr, boolean stdoutTruncated,
                         boolean stderrTruncated) {
        public ProcessResult {
            stdout = stdout.clone();
            stderr = stderr.clone();
        }

        @Override public byte[] stdout() { return stdout.clone(); }
        @Override public byte[] stderr() { return stderr.clone(); }
    }

    private static void requireText(String value, String name) {
        if (value == null || value.isBlank()) throw new IllegalArgumentException(name + " must not be blank");
    }
}
